/* ─────────────────────────────────────────────
   SVG COLORING HELPERS
───────────────────────────────────────────── */

function initSVGColoring(container, selectedColorRef, moveModeRef, onAction) {
  if (!container) return;
  const svg = container.querySelector("svg");
  if (!svg) return;

  const handleEvent = (e) => {
    // Never paint in move mode
    if (moveModeRef && moveModeRef.current) return;
    e.preventDefault();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    // Use elementsFromPoint (plural) to get all stacked elements at the tap point,
    // so decorative non-st0 paths on top don't block the colorable st0 path underneath.
    const elements = document.elementsFromPoint(clientX, clientY);
    for (const el of elements) {
      if (!svg.contains(el) || el === svg) continue;
      if (el.tagName === "path" || el.tagName === "circle" || el.tagName === "ellipse") {
        const cls = el.getAttribute("class") || "";
        if (cls.includes("st0")) {
          const prev = el.style.fill || "#ffffff";
          el.style.fill = selectedColorRef.current;
          onAction({ path: el, prev });
          return;
        }
      }
    }
  };

  if (svg._clickHandler)    svg.removeEventListener("click",      svg._clickHandler);
  if (svg._touchHandler)    svg.removeEventListener("touchstart", svg._touchHandler);
  svg._clickHandler = handleEvent;
  svg._touchHandler = handleEvent;
  svg.addEventListener("click",      svg._clickHandler);
  svg.addEventListener("touchstart", svg._touchHandler, { passive: false });
}

/** Reset all colorable paths to white */
function clearSVGColors(container) {
  if (!container) return;
  container.querySelectorAll('.st0').forEach(p => {
    p.style.fill = '';  // reset to original SVG fill
  });
}

/** Render SVG container to PNG data URL and call onReady(dataUrl). */
function generatePNG(container, onReady) {
  if (!container) return;
  const svg = container.querySelector('svg');
  if (!svg) return;

  const clone = svg.cloneNode(true);
  const vb    = svg.viewBox?.baseVal;
  const svgW  = (vb?.width  > 0 ? vb.width  : null) ?? (svg.getBoundingClientRect().width  || 800);
  const svgH  = (vb?.height > 0 ? vb.height : null) ?? (svg.getBoundingClientRect().height || 600);
  clone.setAttribute('width',  svgW);
  clone.setAttribute('height', svgH);

  const svgBlob = new Blob([new XMLSerializer().serializeToString(clone)],
                           { type: 'image/svg+xml;charset=utf-8' });
  const url = URL.createObjectURL(svgBlob);

  const img = new Image();
  img.onload = () => {
    // iOS Safari (older iPads) caps canvas size around 4096×4096.
    // Compute scale dynamically so the largest dimension stays under the cap.
    const MAX_CANVAS_DIM = 4000;
    const maxScale = Math.min(MAX_CANVAS_DIM / svgW, MAX_CANVAS_DIM / svgH);
    const scale  = Math.min(3, maxScale);
    const canvas = document.createElement('canvas');
    canvas.width  = Math.floor(svgW * scale);
    canvas.height = Math.floor(svgH * scale);
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.scale(scale, scale);
    ctx.drawImage(img, 0, 0);
    URL.revokeObjectURL(url);
    onReady(canvas.toDataURL('image/png'));
  };
  img.onerror = () => URL.revokeObjectURL(url);
  img.src = url;
}

/* ─────────────────────────────────────────────
   MAIN APP
───────────────────────────────────────────── */
// ── Helper: button style ──
function btnStyle(M, disabled, primary) {
  return {
    fontFamily:"'Nunito',sans-serif", fontSize:'0.72rem', fontWeight:800,
    padding:'0 6px', borderRadius:9, cursor: disabled?'not-allowed':'pointer',
    border:`1.5px solid ${disabled?M.borderLt:primary?M.green:M.borderLt}`,
    background: disabled?'#EEF5EE':primary?M.green:M.btnBg,
    color: disabled?M.textLt:primary?'#fff':M.text,
    opacity: disabled?0.5:1, transition:'all 0.15s',
    display:'flex', alignItems:'center', justifyContent:'center',
    overflow:'hidden', boxSizing:'border-box', flexShrink:0,
    minHeight:'40px', height:'40px',
    boxShadow: disabled?'none':primary?'0 2px 8px rgba(74,124,89,0.3)':'0 2px 6px rgba(45,80,53,0.08)',
    whiteSpace:'nowrap',
  };
}

export default function MiloApp() {
  const [screen, setScreen]             = useState("home");
  const [currentPage, setCurrentPage]   = useState(0);
  const [selectedColor, setSelectedColor] = useState(COLORS[0]);
  const [showStoryMobile, setShowStoryMobile] = useState(false);
  const [undoStack, setUndoStack]       = useState([]);  // [{path, prev}]
  const [showAbout, setShowAbout]       = useState(false);
  const [isMobile, setIsMobile]         = useState(false);
  const [isLandscape, setIsLandscape]   = useState(window.innerWidth > window.innerHeight);
  const [zoom, setZoom]                 = useState(1);
  const [pan, setPan]                   = useState({ x: 0, y: 0 });
  const [canvasSize, setCanvasSize]     = useState({ w: 0, h: 0, sideW: 0, landscape: false });
  const [moveMode, setMoveMode]         = useState(false);
  const [toastMsg, setToastMsg]         = useState(null);
  const [exportImg, setExportImg]       = useState(null);
  const [musicOn, setMusicOn]           = useState(true);
  const [showTutorial, setShowTutorial] = useState(false);
  const [tutorialStep, setTutorialStep] = useState(0);
  const [lang, setLang]                 = useState(() => {
    const nav = (navigator.language || 'en').toLowerCase();
    if (nav.startsWith('pt')) return 'pt';
    if (nav.startsWith('es')) return 'es';
    return 'en';
  });
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
  const isPanning                       = useRef(false);
  const lastPan                         = useRef({ x: 0, y: 0 });
  const wrapperRef                      = useRef(null);
  const moveModeRef                     = useRef(false);
  const pageColors                      = useRef({});   // { pageIndex: { elIndex: fill } }
  const prevPageRef                     = useRef(null); // track previous page for save-before-switch

  const svgContainerRef  = useRef(null);   // holds the current SVG
  const selectedColorRef = useRef(selectedColor);

  // Keep ref in sync so SVG event listeners always see latest color
  useEffect(() => { selectedColorRef.current = selectedColor; }, [selectedColor]);
  useEffect(() => { moveModeRef.current = moveMode; }, [moveMode]);

  // Show tutorial on first entry to coloring screen (persisted in localStorage)
  useEffect(() => {
    if (screen === "coloring") {
      try {
        const seen = localStorage.getItem('milo_tutorial_seen_v1');
        if (!seen) {
          setTutorialStep(0);
          setShowTutorial(true);
        }
      } catch { /* localStorage unavailable */ }
    }
  }, [screen]);

  const dismissTutorial = () => {
    setShowTutorial(false);
    try { localStorage.setItem('milo_tutorial_seen_v1', '1'); } catch {}
  };
  const showTutorialAgain = () => {
    setTutorialStep(0);
    setShowTutorial(true);
  };


  // ── Background music ──
  const audioRef = useRef(null);
  useEffect(() => {
    const audio = new Audio(bgMusic);
    audio.loop = true;
    audio.volume = 0.55;
    audioRef.current = audio;
    return () => { audio.pause(); audio.src = ''; };
  }, []);
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    if (screen === 'home' && musicOn) {
      audio.play().catch(() => {});
    } else {
      audio.pause();
      if (screen !== 'home') audio.currentTime = 0;
    }
  }, [screen, musicOn]);

  // Start fresh on mount
  useEffect(() => { pageColors.current = {}; }, []);

  useEffect(() => {
    const compute = () => {
      const rawVw = window.innerWidth;
      const vw  = Math.min(rawVw, 1200); // cap at 1200px so canvas doesn't explode on desktop
      // Use visualViewport when available so we get the *actually visible* height
      // on iOS (excluding Safari URL bar, notch, home indicator area).
      const vh  = (window.visualViewport && window.visualViewport.height) || window.innerHeight;
      const ar  = rawVw / vh;
      // Landscape whenever aspect ratio is clearly wider-than-tall (works for all phone sizes)
      let landscape = ar >= 1.3;
      const mobile    = rawVw < 768;
      // Account for safe-area-inset-top (status bar / notch) and the 3px progress rail
      const safeAreaTop    = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--sat')) || 0;
      const safeAreaLeft   = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--sal')) || 0;
      const safeAreaRight  = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--sar')) || 0;
      const safeAreaBottom = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--sab')) || 0;
      const HEADER    = (mobile ? 38 : 44) + safeAreaTop + 3;
      const PAD       = 6;
      const GAP       = 6;
      const RATIO     = 4/3;

      const bodyH = vh - HEADER;
      const bodyW = vw - (landscape ? safeAreaLeft + safeAreaRight : 0);

      // Minimum sidebar width: needs to fit icon-only bottom nav (~150px)
      // and a 4-col swatch grid + zoom pill. Below this, UI breaks.
      const MIN_SIDE = 150;
      // Minimum canvas width in landscape — below this, fall back to portrait.
      const MIN_CANVAS_W = 260;

      if (landscape) {
        const DOTS_COL = 20 + GAP;
        const availH = bodyH - PAD*2;
        let ch = availH, cw = Math.floor(ch * RATIO);
        let sideW = bodyW - cw - PAD*2 - GAP*2 - DOTS_COL;
        if (sideW < MIN_SIDE) {
          sideW = MIN_SIDE;
          cw = bodyW - sideW - PAD*2 - GAP*2 - DOTS_COL;
          ch = Math.floor(cw / RATIO);
        }
        // If even with min sidebar the canvas is too narrow, fall back to portrait
        if (cw < MIN_CANVAS_W) {
          landscape = false;
        } else {
          setIsMobile(mobile);
          setIsLandscape(true);
          setCanvasSize({ w: Math.floor(cw), h: Math.floor(ch), sideW, landscape: true });
          return;
        }
      }
      // Portrait branch (including landscape fallback)
      setIsMobile(mobile);
      setIsLandscape(false);
      {
        // Bottom mode: canvas fills full width, controls below
        const SW_MAX = 34, SW_GAP = 4;
        const availW = bodyW - PAD*2;            // full width, no sidebar
        const DOTS_H = 16;                        // progress dots row
        const BTN_H  = 34;
        const PAL_H  = (SW_MAX + SW_GAP) * 2 + 14; // ~2 rows of swatches
        const CTRL_EST = PAL_H + BTN_H + BTN_H + GAP*4 + 42; // palette + btns + story
        const availH = bodyH - PAD*2 - DOTS_H - GAP;
        let ch = availH - CTRL_EST;
        let cw = ch * RATIO;
        if (cw > availW) { cw = availW; ch = cw / RATIO; }
        setCanvasSize({ w: Math.floor(cw), h: Math.floor(ch), sideW: Math.floor(cw), landscape: false });
      }
    };

    compute();
    const onOrientationChange = () => setTimeout(compute, 120);
    window.addEventListener("resize", compute);
    window.addEventListener("orientationchange", onOrientationChange);
    // iOS fires visualViewport resize events when the URL bar shows/hides —
    // standard resize events don't cover that case.
    const vv = window.visualViewport;
    if (vv) {
      vv.addEventListener("resize", compute);
      vv.addEventListener("scroll", compute);
    }
    return () => {
      window.removeEventListener("resize", compute);
      window.removeEventListener("orientationchange", onOrientationChange);
      if (vv) {
        vv.removeEventListener("resize", compute);
        vv.removeEventListener("scroll", compute);
      }
    };
  }, []);

  // ── Persist colors helpers ──
  const saveColorsForPage = (pageIdx) => {
    const container = svgContainerRef.current;
    if (!container || pageIdx === null) return;
    const els = container.querySelectorAll('.st0');
    if (!els.length) return;
    const colors = {};
    els.forEach((el, i) => { if (el.style.fill) colors[i] = el.style.fill; });
    pageColors.current[pageIdx] = colors;
  };

  const restoreColorsForPage = (container, pageIdx) => {
    const saved = pageColors.current[pageIdx];
    if (!saved) return;
    const els = container.querySelectorAll('.st0');
    Object.entries(saved).forEach(([i, fill]) => {
      if (els[i]) els[i].style.fill = fill;
    });
  };

  // Inject SVG and attach listeners on screen/page change
  useEffect(() => {
    setZoom(1);
    setPan({ x: 0, y: 0 });

    if (screen !== "coloring") {
      saveColorsForPage(prevPageRef.current);
      return;
    }

    // Save colors of the page we're leaving
    if (prevPageRef.current !== null && prevPageRef.current !== currentPage) {
      saveColorsForPage(prevPageRef.current);
    }
    prevPageRef.current = currentPage;
    setShowStoryMobile(false);

    const container = svgContainerRef.current;
    if (!container) return;
    container.innerHTML = STORY_PAGES[currentPage].svg;
    restoreColorsForPage(container, currentPage);
    // Rebuild undo stack from restored state (start fresh per page)
    setUndoStack([]);
    // Attach listeners immediately in the same tick
    initSVGColoring(
      container,
      selectedColorRef,
      moveModeRef,
      (action) => setUndoStack(prev => {
        const n = [...prev, action];
        return n.length > 20 ? n.slice(-20) : n;
      })
    );
  }, [screen, currentPage]);

  const handleUndo = () => {
    if (!undoStack.length) return;
    const last = undoStack[undoStack.length - 1];
    last.path.style.fill = last.prev;
    setUndoStack(prev => prev.slice(0, -1));
  };

  const handleClear = () => {
    setUndoStack([]);
    clearSVGColors(svgContainerRef.current);
  };

  const handleSave = () => {
    generatePNG(svgContainerRef.current, (dataUrl) => {
      setExportImg(dataUrl);
    });
  };

  const fonts = `@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;700;800&family=Quicksand:wght@400;600;700&family=Nunito:wght@400;600;700;800&display=swap');`;

  const baseStyle = {
    fontFamily: "'Quicksand', 'Baloo 2', sans-serif",
    margin: 0, padding: 0, boxSizing: "border-box",
    minHeight: "100dvh", width: "100%", overflowX: "hidden",
  };

  /* ── Active translations ── */
  const t = TRANSLATIONS[lang];

  /* ═══════════ HOME SCREEN ═══════════ */
  if (screen === "home") {
    /* ─── Shared sticker primitives (Playful Sticker design) ─── */
    const stickerShadow = 'drop-shadow(0 3px 0 rgba(107,66,38,.2)) drop-shadow(0 6px 10px rgba(107,66,38,.15))';
    const Sticker = ({style, children}) => (
      <div style={{position:'absolute', zIndex:2, filter:stickerShadow, ...style}}>{children}</div>
    );
    const MapSticker = () => (
      <div style={{width:78, height:60, background:'#FFF8E7', border:'2px solid #6B4226',
        borderRadius:6, padding:6, position:'relative'}}>
        <div style={{height:2, background:'#6B4226', opacity:.3, margin:'3px 0'}}/>
        <div style={{height:2, background:'#6B4226', opacity:.3, margin:'3px 0'}}/>
        <svg viewBox="0 0 60 40" style={{width:'calc(100% - 12px)', height:30, position:'absolute', bottom:4, left:6}}>
          <path d="M5 25 Q15 15 25 22 T50 18" stroke="#D97757" strokeWidth="1.5" strokeDasharray="2 2" fill="none"/>
          <circle cx="5" cy="25" r="2.5" fill="#E63946"/>
          <path d="M47 14 l3 4 l3 -4 l-1 6 l-4 0 z" fill="#E63946"/>
        </svg>
      </div>
    );
    const CompassSticker = ({size=58}) => (
      <svg width={size} height={size} viewBox="0 0 60 60">
        <circle cx="30" cy="30" r="26" fill="#FFFBF2" stroke="#6B4226" strokeWidth="2.5"/>
        <circle cx="30" cy="30" r="20" fill="none" stroke="#6B4226" strokeWidth="1" opacity=".4"/>
        <text x="30" y="14" textAnchor="middle" fontFamily="'Baloo 2'" fontSize="9" fontWeight="700" fill="#6B4226">N</text>
        <text x="30" y="52" textAnchor="middle" fontFamily="'Baloo 2'" fontSize="9" fontWeight="700" fill="#6B4226">S</text>
        <polygon points="30,18 34,30 30,42 26,30" fill="#D97757"/>
        <polygon points="30,18 34,30 30,30" fill="#E63946"/>
        <circle cx="30" cy="30" r="3" fill="#6B4226"/>
      </svg>
    );
    const Paw = ({size=22}) => (
      <svg width={size} height={size} viewBox="0 0 22 22">
        <ellipse cx="11" cy="14" rx="5" ry="4.5" fill="#6B4226"/>
        <ellipse cx="5" cy="8" rx="2.2" ry="2.5" fill="#6B4226"/>
        <ellipse cx="11" cy="5" rx="2.2" ry="2.5" fill="#6B4226"/>
        <ellipse cx="17" cy="8" rx="2.2" ry="2.5" fill="#6B4226"/>
      </svg>
    );
    const Star = ({size=34}) => (
      <svg width={size} height={size} viewBox="0 0 34 34">
        <path d="M17 2 L20 12 L30 14 L22 20 L25 30 L17 24 L9 30 L12 20 L4 14 L14 12 Z"
          fill="#F3C77B" stroke="#6B4226" strokeWidth="2" strokeLinejoin="round"/>
      </svg>
    );
    const Butterfly = ({size=38}) => (
      <svg width={size} height={size*0.84} viewBox="0 0 40 32">
        <ellipse cx="12" cy="14" rx="9" ry="10" fill="#89C2D9" stroke="#6B4226" strokeWidth="2"/>
        <ellipse cx="28" cy="14" rx="9" ry="10" fill="#89C2D9" stroke="#6B4226" strokeWidth="2"/>
        <ellipse cx="12" cy="22" rx="6" ry="6" fill="#B5DEFF" stroke="#6B4226" strokeWidth="2"/>
        <ellipse cx="28" cy="22" rx="6" ry="6" fill="#B5DEFF" stroke="#6B4226" strokeWidth="2"/>
        <ellipse cx="20" cy="16" rx="2" ry="8" fill="#6B4226"/>
      </svg>
    );
    const Leaf = ({size=34}) => (
      <svg width={size} height={size*1.05} viewBox="0 0 34 36">
        <path d="M17 3 Q30 12 28 28 Q17 34 6 28 Q4 12 17 3 Z" fill="#95C776" stroke="#2D5035" strokeWidth="2"/>
        <path d="M17 5 Q17 30 17 32" stroke="#2D5035" strokeWidth="1.5" fill="none"/>
      </svg>
    );
    const miloOutlineFilter = 'drop-shadow(2px 0 0 #FFFBF2) drop-shadow(-2px 0 0 #FFFBF2) drop-shadow(0 2px 0 #FFFBF2) drop-shadow(0 -2px 0 #FFFBF2) drop-shadow(0 10px 18px rgba(107,66,38,.35))';

    /* Language selector pill */
    const LangSelector = () => (
      <div style={{display:'flex', justifyContent:'center', gap:6, marginTop:10}}>
        {['pt','en','es'].map(l => (
          <button key={l} onClick={() => setLang(l)} style={{
            fontFamily:"'Nunito',sans-serif", fontWeight:800, fontSize:9,
            padding:'3px 9px', borderRadius:9999,
            border:`1.5px solid ${lang === l ? '#6B4226' : 'rgba(107,66,38,.3)'}`,
            background: lang === l ? '#6B4226' : 'transparent',
            color: lang === l ? '#FFFBF2' : 'rgba(107,66,38,.6)',
            cursor:'pointer', letterSpacing:'0.08em', textTransform:'uppercase',
            transition:'all 0.18s',
          }}>
            {l === 'pt' ? 'PT' : l === 'en' ? 'EN' : 'ES'}
          </button>
        ))}
      </div>
    );

    /* Card inner content — same in portrait and landscape */
    const CardContent = ({centered=true}) => (
      <>
        <span style={{display:'inline-flex', alignItems:'center', gap:6,
          fontFamily:"'Nunito',sans-serif", fontWeight:800, fontSize:10,
          letterSpacing:'0.14em', textTransform:'uppercase', color:'#6B4226',
          background:'#FFF0D0', border:'1px solid #F3C77B',
          padding:'6px 12px', borderRadius:9999, width:'fit-content',
          animation:'fadeUp 0.8s ease-out 0.1s both'}}>
          <span style={{width:6, height:6, borderRadius:'50%', background:'#D97757', flexShrink:0}}/>
          {t.badge}
        </span>
        <h1 style={{fontFamily:"'Baloo 2',cursive", fontWeight:800,
          fontSize: isLandscape && isMobile ? 24 : 32, color:'#6B4226',
          margin: isLandscape && isMobile ? '4px 0 2px' : '10px 0 4px',
          lineHeight:1.03, letterSpacing:'-0.015em', textAlign:'center',
          whiteSpace:'pre-line',
          animation:'fadeUp 0.8s ease-out 0.2s both'}}>
          {t.homeTitle}
        </h1>
        <p style={{fontFamily:"'Quicksand',sans-serif", fontWeight:500, fontSize:13, color:'#8B5A3C',
          margin: isLandscape && isMobile ? '0 0 8px' : '0 0 14px', lineHeight:1.5, textAlign:'center',
          animation:'fadeUp 0.8s ease-out 0.3s both'}}>
          {t.homeSub}
        </p>
        <div style={{display:'flex', flexDirection:'column', alignItems:'center',
          gap: isLandscape && isMobile ? 2 : 4,
          marginBottom: isLandscape && isMobile ? 8 : 14,
          animation:'fadeUp 0.8s ease-out 0.4s both'}}>
          <button onClick={() => setScreen("coloring")} style={{
            fontFamily:"'Baloo 2',cursive", fontWeight:700, fontSize:15,
            padding: isLandscape && isMobile ? '9px 20px' : '12px 24px', borderRadius:9999, border:0,
            background:'#D97757', color:'#FFFBF2', cursor:'pointer',
            boxShadow:'0 10px 24px -8px rgba(217,119,87,.45), inset 0 -3px 0 rgba(0,0,0,.1)',
            display:'inline-flex', alignItems:'center', gap:8}}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="9"/><circle cx="8.5" cy="10.5" r="1" fill="currentColor"/><circle cx="15.5" cy="10.5" r="1" fill="currentColor"/><circle cx="9.5" cy="14" r="1" fill="currentColor"/><circle cx="14.5" cy="14" r="1" fill="currentColor"/></svg>
            {t.startBtn}
          </button>
          <button onClick={() => setShowAbout(true)} style={{
            fontFamily:"'Quicksand',sans-serif", fontWeight:600, fontSize:13,
            color:'#8B5A3C', border:0, background:'transparent', cursor:'pointer',
            textDecoration:'underline', textUnderlineOffset:4,
            textDecorationColor:'rgba(139,90,60,.4)', padding:'4px 8px'}}>
            {t.aboutLink}
          </button>
        </div>
        <div style={{borderTop:'1px dashed rgba(107,66,38,.25)',
          paddingTop: isLandscape && isMobile ? 8 : 12, width:'100%',
          display:'flex', flexDirection:'column', alignItems:'center',
          gap: isLandscape && isMobile ? 4 : 6,
          animation:'fadeUp 0.8s ease-out 0.5s both'}}>
          <div style={{fontFamily:"'Nunito',sans-serif", fontWeight:700, fontSize:8,
            letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(107,66,38,.6)'}}>
            {t.footerLabel}
          </div>
          <div style={{display:'flex', alignItems:'center', gap:16}}>
            <img src={logoFise} alt="Instituto Fise" style={{height: isLandscape && isMobile ? 54 : 80, width:'auto', objectFit:'contain'}}/>
            <div style={{width:1, height:40, background:'rgba(107,66,38,.2)'}}/>
            <img src={logoBlumetti} alt="Dr. Francesco Blumetti" style={{height: isLandscape && isMobile ? 42 : 60, width:'auto', objectFit:'contain'}}/>
          </div>
          <LangSelector/>
        </div>
      </>
    );

    /* Trail path chooser */
    const trailPath = isLandscape
      ? "M 40 60 Q 120 140, 90 220 T 200 330 Q 280 360, 390 340"
      : "M 60 100 Q 120 180, 90 260 T 160 420 Q 220 500, 180 580 T 260 720";

    return (
      <div style={{
        ...baseStyle,
        background: isLandscape
          ? 'radial-gradient(ellipse at 30% 50%, #FFF4DE 0%, #FCE8BF 55%, #F5D088 100%)'
          : 'radial-gradient(ellipse at 50% 40%, #FFF4DE 0%, #FCE8BF 60%, #F5D088 100%)',
        position:"relative", overflow:"hidden", height:"100dvh",
        display:"flex", flexDirection: isLandscape ? "row" : "column",
      }}>
        <style>{fonts}{`
          @keyframes float { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-10px)} }
          @keyframes fadeUp { from{opacity:0;transform:translateY(24px)} to{opacity:1;transform:translateY(0)} }
        `}</style>


        {/* Music toggle button */}
        <button
          onClick={() => setMusicOn(m => !m)}
          title={musicOn ? 'Desligar música' : 'Ligar música'}
          style={{
            position:'absolute', top:`calc(env(safe-area-inset-top,0px) + 14px)`,
            right:`calc(env(safe-area-inset-right,0px) + 14px)`,
            zIndex:10, width:36, height:36, borderRadius:'50%', border:0,
            background:'rgba(107,66,38,.18)', backdropFilter:'blur(6px)',
            WebkitBackdropFilter:'blur(6px)',
            color:'#6B4226', cursor:'pointer',
            display:'flex', alignItems:'center', justifyContent:'center',
            transition:'background 0.2s',
          }}>
          {musicOn
            ? <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/></svg>
            : <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><line x1="23" y1="9" x2="17" y2="15"/><line x1="17" y1="9" x2="23" y2="15"/></svg>
          }
        </button>

        {isLandscape ? (
          /* ───────── LANDSCAPE ───────── */
          <>
            {/* LEFT — sticker scene + Milo */}
            <div style={{position:'relative', flex:'1.1 0 0', overflow:'hidden'}}>
              {/* Dashed trail */}
              <svg style={{position:'absolute', top:0, left:0, width:'100%', height:'100%', zIndex:1}}
                viewBox="0 0 430 390" preserveAspectRatio="none">
                <path d={trailPath} fill="none" stroke="#C89B5F" strokeWidth="3"
                  strokeDasharray="2 10" strokeLinecap="round" opacity=".55"/>
              </svg>
              <Sticker style={{top:24, left:20, transform:'rotate(-8deg)'}}><MapSticker/></Sticker>
              <Sticker style={{top:18, right:30, transform:'rotate(12deg)'}}><CompassSticker size={50}/></Sticker>
              <Sticker style={{top:100, left:30, transform:'rotate(-18deg)'}}><Star size={28}/></Sticker>
              <Sticker style={{bottom:80, left:24, transform:'rotate(20deg)'}}><Leaf size={28}/></Sticker>
              <Sticker style={{top:140, right:50, transform:'rotate(-10deg)'}}><Butterfly size={32}/></Sticker>
              {[{t:210,l:60,r:-15},{t:260,l:100,r:10},{t:300,l:200,r:-8},{t:320,l:320,r:18}].map((p,i)=>(
                <Sticker key={i} style={{top:p.t, left:p.l, transform:`rotate(${p.r}deg)`}}><Paw size={18}/></Sticker>
              ))}
              {/* Milo centered */}
              <div style={{position:'absolute', inset:0, display:'flex', alignItems:'center',
                justifyContent:'center', zIndex:3, paddingBottom:20}}>
                <img src={miloSprite} alt="Milo" style={{
                  maxHeight: isMobile ? 'min(78vh, 240px)' : 'min(78vh, 420px)', width:'auto', height:'auto',
                  filter: miloOutlineFilter,
                  animation:'fadeUp 0.8s ease-out, float 4s ease-in-out infinite 1s'}}/>
              </div>
            </div>

            {/* RIGHT — polaroid card */}
            <div style={{flex:'1 0 0', display:'flex', flexDirection:'column', alignItems:'center',
              padding:'20px 28px 20px 10px', position:'relative', zIndex:4, overflowY:'auto'}}>
              <div style={{background:'#FFFBF2', borderRadius:22, padding: isMobile ? '14px 18px 12px' : '22px 24px 20px',
                border:'2px solid #6B4226', width:'100%', maxWidth: isMobile ? 420 : 540,
                boxShadow:'0 8px 0 rgba(107,66,38,.15), 0 20px 40px -10px rgba(107,66,38,.25)',
                transform:'rotate(-1.2deg)',
                display:'flex', flexDirection:'column', alignItems:'center',
                marginTop:'auto', marginBottom:'auto', flexShrink:0,
                zoom: isMobile ? Math.min(1, (window.innerHeight - 44) / 342) : 1 }}>
                <CardContent/>
              </div>
            </div>
          </>
        ) : (
          /* ───────── PORTRAIT ───────── */
          <>
            {/* Dashed trail */}
            <svg style={{position:'absolute', top:0, left:0, width:'100%', height:'100%', zIndex:1}}
              viewBox="0 0 390 780" preserveAspectRatio="xMidYMid slice">
              <path d={trailPath} fill="none" stroke="#C89B5F" strokeWidth="3"
                strokeDasharray="2 10" strokeLinecap="round" opacity=".55"/>
            </svg>
            {/* Stickers — positioned by % of viewport so they stay on the scene at any size */}
            <Sticker style={{top:'7%', left:'6%', transform:'rotate(-8deg)'}}><MapSticker/></Sticker>
            <Sticker style={{top:'14%', right:'7%', transform:'rotate(12deg)'}}><CompassSticker/></Sticker>
            <Sticker style={{top:'3%', right:'25%', transform:'rotate(-18deg)'}}><Star/></Sticker>
            <Sticker style={{top:'36%', right:'10%', transform:'rotate(-10deg)'}}><Butterfly/></Sticker>
            <Sticker style={{bottom:'38%', left:'8%', transform:'rotate(20deg)'}}><Leaf/></Sticker>
            {[{t:'22%',l:'22%',r:-15},{t:'28%',l:'17%',r:10},{t:'36%',l:'32%',r:-8},{t:'44%',l:'36%',r:18}].map((p,i)=>(
              <Sticker key={i} style={{top:p.t, left:p.l, transform:`rotate(${p.r}deg)`}}><Paw/></Sticker>
            ))}

            {/* Milo sprite — flexible centered zone above card */}
            <div style={{position:'relative', zIndex:3, flex:1, minHeight:0,
              display:'flex', alignItems:'flex-end', justifyContent:'center', width:'100%',
              paddingTop:24, paddingBottom:12}}>
              <img src={miloSprite} alt="Milo" style={{
                maxHeight:'85%', maxWidth: isMobile ? 'min(210px, 55vw)' : 'min(340px, 45vw)',
                width:'auto', height:'auto',
                filter: miloOutlineFilter,
                animation:'fadeUp 0.8s ease-out, float 4s ease-in-out infinite 1s'}}/>
            </div>

            {/* Polaroid card */}
            <div style={{position:'relative', zIndex:5, margin:`0 20px calc(env(safe-area-inset-bottom, 0px) + 20px)`,
              background:'#FFFBF2', borderRadius:22, padding:'20px 22px 18px',
              border:'2px solid #6B4226',
              boxShadow:'0 8px 0 rgba(107,66,38,.15), 0 20px 40px -10px rgba(107,66,38,.25)',
              transform:'rotate(-1.2deg)',
              display:'flex', flexDirection:'column', alignItems:'center'}}>
              <CardContent/>
            </div>
          </>
        )}

        {/* About modal — bottom sheet */}
        {showAbout && (
          <div style={{ position:'fixed', inset:0, background:'rgba(20,25,21,.55)',
            backdropFilter:'blur(6px)', WebkitBackdropFilter:'blur(6px)',
            display:'flex', alignItems:'flex-end', justifyContent:'center', zIndex:1000 }}
            onClick={() => setShowAbout(false)}>
            <div style={{ background:'#FFFBF2', borderRadius:'28px 28px 0 0',
              padding:'22px 24px 32px', borderTop:'5px solid #F3C77B',
              boxShadow:'0 -20px 50px -20px rgba(45,80,53,.3)',
              width:'100%', maxWidth:480 }}
              onClick={e => e.stopPropagation()}>
              <div style={{ width:40, height:4, background:'rgba(45,80,53,.15)', borderRadius:9999, margin:'0 auto 16px' }}/>
              <div style={{ display:'flex', alignItems:'center', gap:14, marginBottom:16 }}>
                <div style={{ width:72, height:96, borderRadius:20, background:'#FFF6E6',
                  border:'1px solid #F3E4C0', flexShrink:0, overflow:'hidden',
                  display:'flex', alignItems:'flex-end', justifyContent:'center', padding:'4px 4px 0' }}>
                  <img src={miloSprite} alt="Milo" style={{ maxWidth:'100%', maxHeight:'100%', objectFit:'contain', objectPosition:'center bottom' }}/>
                </div>
                <div>
                  <div style={{ fontFamily:"'Nunito',sans-serif", fontWeight:700, fontSize:'0.7rem',
                    letterSpacing:'0.14em', textTransform:'uppercase', color:'#5C4033' }}>{t.charLabel}</div>
                  <h2 style={{ fontFamily:"'Baloo 2',cursive", fontWeight:700, fontSize:'1.4rem',
                    color:'#6B4226', margin:'2px 0 0', lineHeight:1.1 }}>Milo</h2>
                </div>
              </div>
              <p style={{ fontFamily:"'Quicksand',sans-serif", color:'#5C4033', fontSize:'0.92rem', lineHeight:1.65, margin:'0 0 10px' }}>
                {t.aboutBody1}
              </p>
              <p style={{ fontFamily:"'Quicksand',sans-serif", color:'#5C4033', fontSize:'0.92rem', lineHeight:1.65, margin:'0 0 0' }}>
                {t.aboutBody2}
              </p>
              <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:8, margin:'16px 0' }}>
                {t.stats.map(([n,l]) => (
                  <div key={l} style={{ background:'#FFF6E6', border:'1px solid #F3E4C0', borderRadius:14, padding:'10px 8px', textAlign:'center' }}>
                    <div style={{ fontFamily:"'Baloo 2',cursive", fontWeight:700, fontSize:'1.2rem', color:'#6B4226', lineHeight:1 }}>{n}</div>
                    <div style={{ fontFamily:"'Nunito',sans-serif", fontWeight:700, fontSize:'0.62rem', letterSpacing:'0.08em', textTransform:'uppercase', color:'#5C4033', marginTop:4 }}>{l}</div>
                  </div>
                ))}
              </div>
              <button onClick={() => setShowAbout(false)} style={{
                display:'block', width:'100%', fontFamily:"'Nunito',sans-serif", fontWeight:700,
                fontSize:'0.9rem', color:'#fff', padding:'12px 0', borderRadius:14, border:0,
                background:'#6B4226', cursor:'pointer',
              }}>{t.closeAbout}</button>
            </div>
          </div>
        )}
      </div>
    );
  }

  /* ═══════════ COLORING SCREEN ═══════════ */
  const page = STORY_PAGES[currentPage];
  const { w: cw, h: ch, sideW, landscape: isLandscapeMode } = canvasSize;

  // ── Design tokens ──
  const M = {
    bg:       '#FDFBF5',   canvas:  '#FFFFFF',
    border:   '#ECE4D3',   borderLt:'#ECE4D3',
    green:    '#4A7C59',   greenDk: '#2D5035',
    header:   '#FDFBF5',
    text:     '#2D5035',   textMid: '#5A8060', textLt: '#9DC4A0',
    panel:    '#FFFFFF',   btnBg:   '#FDFBF5',
    orange:   '#FF8C42',
    shadow:   '0 4px 16px rgba(45,80,53,0.12)',
    shadowSm: '0 2px 6px rgba(45,80,53,0.08)',
    shadowIn: 'inset 0 2px 8px rgba(45,80,53,0.10), inset 0 0 0 1px rgba(45,80,53,0.06)',
  };

  // ── Constants (must match compute() in resize effect) ──
  const SW_MIN = 14, SW_MAX = 34, SW_GAP = 4;
  const PAD = 6, GAP = 6;
  const STORY_H = 38;
  const MIN_ROW_H = 3 * 36 + 2 * GAP + 30; // 3 buttons × 36px + gaps + padding

  // ── Zoom/pan handlers ──
  const clampPan = (px, py, nz) => {
    const maxX = cw * (nz - 1) / 2;
    const maxY = ch * (nz - 1) / 2;
    return {
      x: Math.max(-maxX, Math.min(maxX, px)),
      y: Math.max(-maxY, Math.min(maxY, py)),
    };
  };
  const zoomIn  = () => {
    const nz = Math.min(zoom + 0.25, 3);
    setZoom(nz);
    if (nz === 1) setPan({ x: 0, y: 0 });
  };
  const zoomOut = () => {
    const nz = Math.max(zoom - 0.25, 1);
    setZoom(nz);
    // Re-clamp pan so image never slides outside its bounds at the new zoom level
    setPan(prev => nz === 1 ? { x: 0, y: 0 } : clampPan(prev.x, prev.y, nz));
  };

  const onPointerDown = (e) => {
    if (!moveModeRef.current) return;
    isPanning.current = true;
    lastPan.current = { x: e.clientX - pan.x, y: e.clientY - pan.y };
    e.currentTarget.setPointerCapture(e.pointerId);
  };
  const onPointerMove = (e) => {
    if (!isPanning.current) return;
    setPan(prev => clampPan(e.clientX - lastPan.current.x, e.clientY - lastPan.current.y, zoom));
  };
  const onPointerUp = () => { isPanning.current = false; };

  // ── Toggle move mode ──
  const toggleMove = () => {
    const nm = !moveMode;
    setMoveMode(nm);
    moveModeRef.current = nm;
    // Do NOT reset pan — keep image position when switching modes
  };

  // ── Panel component ──
  const Panel = ({ children, style }) => (
    <div style={{ background: M.panel, border: `1.5px solid ${M.borderLt}`, borderRadius: 11,
      boxShadow: M.shadowSm, padding: '5px', display: 'flex', alignItems: 'center',
      justifyContent: 'center', gap: '3px', flexWrap: 'wrap', overflow: 'hidden',
      minWidth: 0, minHeight: 0, boxSizing: 'border-box', ...style }}>
      {children}
    </div>
  );

  // ── Compute palette layout ──
  const palAvailW  = isLandscapeMode ? (sideW || 78) - 16 : (cw || 300) - 16;
  const palAvailH  = isLandscapeMode ? (ch || 200) - MIN_ROW_H - STORY_H - GAP * 2 - 16 : 999;
  let palBestSw = SW_MIN, palBestCols = 1;
  for (let sw = SW_MAX; sw >= SW_MIN; sw--) {
    let cols = 1;
    for (let c = COLORS.length; c >= 1; c--) {
      if (c * sw + (c - 1) * SW_GAP <= palAvailW) { cols = c; break; }
    }
    const rows = Math.ceil(COLORS.length / cols);
    if (!isLandscapeMode || rows * sw + (rows - 1) * SW_GAP <= palAvailH) {
      palBestSw = sw; palBestCols = cols; break;
    }
  }
  const palRows = Math.ceil(COLORS.length / palBestCols);
  const palPanelH = palRows * palBestSw + (palRows - 1) * SW_GAP + 16;

  // ── BTN_GROUPS for sizeButtonPanels ──
  // (called via useEffect after render — see below)

  // ── Story modal ──
  const storyModalContent = (
    <>
      {/* Chapter eyebrow */}
      <div style={{ fontFamily:"'Nunito',sans-serif", fontWeight:700, fontSize:'0.7rem',
        letterSpacing:'0.18em', textTransform:'uppercase', color:'#D4B87A',
        marginBottom:16, display:'inline-flex', alignItems:'center', gap:10 }}>
        <span style={{ width:24, height:1, background:'rgba(212,184,122,.5)', display:'inline-block' }}/>
        {t.chapter} {currentPage + 1}
        <span style={{ width:24, height:1, background:'rgba(212,184,122,.5)', display:'inline-block' }}/>
      </div>
      <h2 style={{ fontFamily:"'Baloo 2',cursive", fontWeight:600, color:'#FFF4DC',
        fontSize:'1.6rem', margin:'0 0 18px', lineHeight:1.2, letterSpacing:'-0.01em' }}>
        {t.pages[currentPage].label}
      </h2>
      <p style={{ fontFamily:"'Quicksand',sans-serif", fontWeight:400, color:'rgba(255,244,220,.82)',
        lineHeight:1.7, fontSize:'0.96rem', maxWidth:290, margin:'0 0 32px' }}>
        {t.pages[currentPage].text}
      </p>
      <button onClick={() => setShowStoryMobile(false)} style={{
        fontFamily:"'Baloo 2',cursive", fontWeight:600, color:'#1F2A24', fontSize:'0.95rem',
        padding:'12px 28px', borderRadius:9999, border:0, background:'#FFF4DC', cursor:'pointer',
        display:'inline-flex', alignItems:'center', gap:10, flexShrink:0,
        boxShadow:'0 10px 24px -10px rgba(255,216,158,.4)',
      }}>
        {t.continueBtn}
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
      </button>
    </>
  );

  const StoryModal = () => showStoryMobile ? (
    isLandscapeMode ? (
      /* Landscape: overlay within canvas bounds */
      <div style={{ position:'absolute', inset:0, zIndex:50,
        background:'radial-gradient(ellipse at 50% 20%, rgba(255,216,158,.22), transparent 60%), linear-gradient(180deg, #1F2A24 0%, #141915 100%)',
        borderRadius:'inherit',
        padding:'24px 34px 24px', display:'flex', flexDirection:'column',
        alignItems:'center', justifyContent:'safe center', overflowY:'auto',
        WebkitOverflowScrolling:'touch', textAlign:'center',
        animation:'mFadeIn 0.2s ease-out' }}>
        {storyModalContent}
      </div>
    ) : (
      /* Portrait: fixed overlay below header — scrollable, never clips */
      <div style={{
        position:'fixed',
        top:`calc(${isMobile ? 46 : 52}px + env(safe-area-inset-top, 0px))`,
        left:0, right:0, bottom:0,
        zIndex:200,
        background:'radial-gradient(ellipse at 50% 20%, rgba(255,216,158,.22), transparent 60%), linear-gradient(180deg, #1F2A24 0%, #141915 100%)',
        display:'flex', flexDirection:'column', alignItems:'center',
        overflowY:'auto', WebkitOverflowScrolling:'touch',
        textAlign:'center', animation:'mFadeIn 0.2s ease-out',
      }}>
        {/* inner wrapper: centers when short, scrolls when long */}
        <div style={{
          display:'flex', flexDirection:'column', alignItems:'center',
          justifyContent:'center', flex:1,
          padding:`48px 34px calc(40px + env(safe-area-inset-bottom, 0px))`,
          minHeight:'100%', boxSizing:'border-box',
        }}>
          {storyModalContent}
        </div>
      </div>
    )
  ) : null;

  const Sidebar = () => {
    const iconBtn = (onClick, label, active=false, disabled=false, children) => (
      <button onClick={disabled ? undefined : onClick} title={label} style={{
        height:36, minWidth:36, padding:'0 10px', borderRadius:12, border:0,
        background: active ? '#C8DFC8' : 'transparent',
        color: disabled ? '#C8DFC8' : M.greenDk,
        fontFamily:"'Nunito',sans-serif", fontWeight:700, fontSize:'0.8rem',
        cursor: disabled ? 'default' : 'pointer', opacity: disabled ? 0.4 : 1,
        display:'inline-flex', alignItems:'center', justifyContent:'center', gap:6,
      }}>{children}</button>
    );

    return (
      <div style={{
        width: isLandscapeMode ? (sideW || 78) : (cw || '100%'),
        flexShrink: 0, display: 'flex', flexDirection: 'column',
        gap: GAP, overflow: 'hidden',
        ...(isLandscapeMode ? { height: ch, paddingBottom: 'env(safe-area-inset-bottom, 0px)' } : {}) }}>

        {/* Floating palette dock */}
        <div style={{ margin:`0`, padding:'14px 14px 12px', background:'#fff',
          borderRadius:26, border:`1px solid #ECE4D3`,
          boxShadow:'0 12px 30px -14px rgba(45,80,53,.22)',
          display:'flex', flexDirection:'column', gap:12,
          ...(isLandscapeMode ? { flex:'1 1 0', minHeight:0, overflow:'hidden' } : {}) }}>

          {/* Swatches — wrapper encolhível em landscape para o tool row nunca ser cortado */}
          {(() => {
            const availW = isLandscapeMode
              ? (sideW || 300) - 28
              : (cw || 300) - 28;
            const cols = availW >= 240 ? 10 : availW >= 150 ? 5 : 4;
            const gap = cols === 10 ? 3 : 5;
            const maxSwatchPx = cols === 10 ? 32 : cols === 5 ? 44 : 52;
            return (
              <div style={isLandscapeMode ? { flex:'1 1 0', minHeight:0, overflow:'visible' } : {}}>
                <div style={{
                  display:'grid',
                  gridTemplateColumns:`repeat(${cols}, minmax(0, ${maxSwatchPx}px))`,
                  justifyContent:'center',
                  gap,
                }}>
                  {COLORS.map(c => (
                    <button key={c} onClick={() => setSelectedColor(c)} style={{
                      aspectRatio:'1', width:'100%', height:'auto',
                      borderRadius:9999, border:0, cursor:'pointer',
                      background:c, transition:'transform .14s',
                      transform: selectedColor === c ? 'scale(1.18)' : 'scale(1)',
                      position:'relative', zIndex: selectedColor === c ? 2 : 1,
                      boxShadow: selectedColor === c
                        ? `0 0 0 2px #fff, 0 0 0 4px ${M.greenDk}, inset 0 0 0 1px rgba(45,80,53,.08)`
                        : c === '#FFFFFF'
                          ? 'inset 0 0 0 1px rgba(45,80,53,.18)'
                          : 'inset 0 0 0 1px rgba(45,80,53,.08)',
                    }}/>
                  ))}
                </div>
              </div>
            );
          })()}

          {/* Tool row — flexShrink:0 garante que zoom nunca seja cortado */}
          <div style={{
            flexShrink: 0,
            display:'flex',
            flexDirection: isLandscapeMode ? 'column' : 'row',
            alignItems: isLandscapeMode ? 'stretch' : 'center',
            justifyContent:'space-between',
            gap: isLandscapeMode ? 8 : 6,
          }}>
            {/* Linha 1: undo + clear + draw + move (wrap se não couber) */}
            <div style={{
              display:'flex', gap:4, alignItems:'center',
              flexWrap: 'wrap',
              justifyContent: isLandscapeMode ? 'center' : 'flex-start',
            }}>
              {iconBtn(handleUndo, t.undoLabel, false, undoStack.length===0,
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 14l-4-4 4-4"/><path d="M5 10h9a5 5 0 0 1 0 10h-3"/></svg>
              )}
              {iconBtn(handleClear, t.clearLabel, false, false,
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/></svg>
              )}
              {/* Draw mode */}
              {iconBtn(() => { if (moveMode) toggleMove(); }, t.drawLabel, !moveMode, false,
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z"/></svg>
              )}
              {/* Move mode */}
              {iconBtn(() => { if (!moveMode) toggleMove(); }, t.moveLabel, moveMode, false,
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12V7a2 2 0 0 1 4 0v4"/><path d="M9 11V5a2 2 0 0 1 4 0v6"/><path d="M13 11V6a2 2 0 0 1 4 0v7"/><path d="M17 13v-2a2 2 0 0 1 4 0v5a6 6 0 0 1-6 6H11a6 6 0 0 1-6-6v-2"/></svg>
              )}
              {/* Save */}
              {iconBtn(handleSave, t.saveBtn, false, false,
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
              )}
              {/* Help / re-show tutorial */}
              {iconBtn(showTutorialAgain, t.helpBtn, false, false,
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
              )}
            </div>

            {/* Linha 2 (landscape) ou à direita (portrait): zoom pill */}
            <div style={{
              display:'flex', alignItems:'center',
              background:'#FDFBF5', border:'1px solid #ECE4D3',
              borderRadius:9999, padding:'2px',
              ...(isLandscapeMode
                ? { width:'100%', justifyContent:'space-between' }
                : {}),
            }}>
              <button onClick={zoomOut} disabled={zoom<=1} style={{
                height:28, minWidth:28, borderRadius:9999, border:0,
                background:'transparent', color:zoom<=1?'#C8DFC8':M.greenDk,
                cursor:zoom<=1?'default':'pointer', display:'inline-flex',
                alignItems:'center', justifyContent:'center', flexShrink:0,
              }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round"><path d="M6 12h12"/></svg>
              </button>
              <span style={{ padding:'0 8px', fontFamily:"'JetBrains Mono',ui-monospace,monospace",
                fontSize:'0.72rem', color:M.textMid, fontWeight:700 }}>
                {Math.round(zoom*100)}%
              </span>
              <button onClick={zoomIn} disabled={zoom>=3} style={{
                height:28, minWidth:28, borderRadius:9999, border:0,
                background:'transparent', color:zoom>=3?'#C8DFC8':M.greenDk,
                cursor:zoom>=3?'default':'pointer', display:'inline-flex',
                alignItems:'center', justifyContent:'center', flexShrink:0,
              }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round"><path d="M12 6v12M6 12h12"/></svg>
              </button>
            </div>
          </div>
        </div>

        {/* Bottom nav — esconde texto dos botões quando sidebar estreita em landscape */}
        {(() => {
          // Quanto espaço precisamos para mostrar "Anterior" + "1 / 14" + "Próxima" sem estourar:
          // ~110 + ~45 + ~120 + paddings + gaps ≈ 300px. Abaixo disso → icon-only.
          const showNavText = !isLandscapeMode || (sideW || 999) >= 300;
          const isLast = currentPage >= STORY_PAGES.length - 1;
          return (
        <div style={{ background:'#FDFBF5', border:`1px solid #ECE4D3`,
          borderRadius: isLandscapeMode ? 16 : 0,
          padding:`8px ${showNavText?16:8}px ${isLandscapeMode ? '8px' : 'calc(env(safe-area-inset-bottom,0px) + 10px)'}`,
          display:'flex', alignItems:'center', justifyContent:'space-between', gap: showNavText?10:4,
          flexShrink:0, overflow:'hidden', minWidth:0, boxSizing:'border-box' }}>
          <button onClick={() => { if(currentPage>0) setCurrentPage(p=>p-1); }}
            disabled={currentPage===0}
            title="Anterior"
            style={{ background:'transparent', border:0, color:currentPage===0?'#C8DFC8':M.greenDk,
              fontFamily:"'Nunito',sans-serif", fontWeight:700, fontSize:'0.82rem',
              padding: showNavText ? '8px 12px' : '8px 8px', borderRadius:12,
              cursor:currentPage===0?'default':'pointer',
              display:'inline-flex', alignItems:'center', gap:showNavText?8:0,
              opacity:currentPage===0?0.4:1, flexShrink:0, whiteSpace:'nowrap' }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M19 12H5M11 6l-6 6 6 6"/></svg>
            {showNavText && t.prevBtn}
          </button>
          <span style={{ fontFamily:"'JetBrains Mono',ui-monospace,monospace", fontWeight:700,
            color:M.textMid, fontSize:'0.78rem', whiteSpace:'nowrap', flexShrink:0 }}>
            {currentPage+1} / {STORY_PAGES.length}
          </span>
          <button onClick={() => { if(!isLast) setCurrentPage(p=>p+1); }}
            disabled={isLast}
            title={t.nextBtn}
            style={{ background: isLast ? '#C8DFC8' : M.greenDk, border:0, color:'#fff',
              fontFamily:"'Nunito',sans-serif", fontWeight:700, fontSize:'0.82rem',
              padding: showNavText ? '10px 18px' : '10px 10px', borderRadius:9999,
              cursor: isLast ? 'default' : 'pointer',
              display:'inline-flex', alignItems:'center', gap:showNavText?8:0, flexShrink:0,
              whiteSpace:'nowrap', opacity: isLast ? 0.45 : 1,
              boxShadow: isLast ? 'none' : '0 4px 12px rgba(45,80,53,.25)' }}>
            {showNavText && t.nextBtn}
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
          </button>
        </div>
          );
        })()}
      </div>
    );
  };



  return (
    <div style={{ fontFamily:"'Nunito',sans-serif", background: M.bg,
      display:'flex', flexDirection:'column', height:'100dvh', width:'100%', overflow:'hidden',
      maxHeight:'100dvh' }}>
      <style>{fonts}{`
        @keyframes mFadeIn { from{opacity:0;transform:scale(0.97)} to{opacity:1;transform:scale(1)} }
        @keyframes ripple { 0%{transform:translate(-50%,-50%) scale(0);opacity:0.5} 100%{transform:translate(-50%,-50%) scale(4);opacity:0} }
        .ripple { position:absolute;width:40px;height:40px;border-radius:50%;pointer-events:none;animation:ripple 0.5s ease-out forwards;border:2px solid currentColor; }
        .st0 { transition: fill 0.18s ease; cursor: crosshair; }
        @media (hover: hover) { .st0:hover { opacity: 0.85; } }
        *::-webkit-scrollbar { width: 3px; }
        *::-webkit-scrollbar-thumb { background: #9DC4A0; border-radius: 3px; }
      `}</style>

      {/* HEADER — paper-cream bar */}
      <div style={{
        minHeight: `calc(${isMobile ? 38 : 44}px + env(safe-area-inset-top, 0px))`,
        flexShrink: 0,
        display:'flex', alignItems:'flex-end', justifyContent:'space-between',
        padding:`env(safe-area-inset-top,0px) calc(14px + env(safe-area-inset-right,0px)) 0 calc(14px + env(safe-area-inset-left,0px))`,
        background: M.header,
        borderBottom:`1px solid ${M.border}` }}>
        {/* Back button */}
        <button onClick={() => setScreen('home')} style={{
          width:38, height:38, borderRadius:14, border:0,
          background:'transparent', color:M.greenDk,
          display:'inline-flex', alignItems:'center', justifyContent:'center',
          cursor:'pointer', flexShrink:0,
        }}>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M15 18l-6-6 6-6"/></svg>
        </button>
        {/* Center: title only */}
        <div style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:2, flex:1, overflow:'hidden' }}>
          <span style={{ fontFamily:"'Baloo 2',cursive", fontWeight:700, fontSize:'1rem',
            color:M.greenDk, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', maxWidth:'100%' }}>
            {t.pages[currentPage].label}
          </span>
        </div>
        {/* Story toggle */}
        <button onClick={() => setShowStoryMobile(s => !s)} style={{
          width:38, height:38, borderRadius:14, border:0,
          background: showStoryMobile ? M.greenDk : 'transparent',
          color: showStoryMobile ? '#fff' : M.greenDk,
          display:'inline-flex', alignItems:'center', justifyContent:'center',
          cursor:'pointer', flexShrink:0, transition:'all 0.18s',
        }}>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M4 7h16M4 12h16M4 17h16"/></svg>
        </button>
      </div>

      {/* PROGRESS RAIL */}
      <div style={{ height:3, background:'rgba(45,80,53,.08)', flexShrink:0, overflow:'hidden' }}>
        <div style={{ height:'100%', width:`${((currentPage+1)/STORY_PAGES.length)*100}%`,
          background:M.orange, borderRadius:9999, transition:'width 0.3s ease' }}/>
      </div>

      {/* BODY */}
      {cw > 0 && (
        <div style={{ flex:1, minHeight:0, display:'flex',
          flexDirection: isLandscapeMode ? 'row' : 'column',
          padding: isLandscapeMode
            ? `${PAD}px calc(env(safe-area-inset-right, 0px) + ${PAD}px) ${PAD}px calc(env(safe-area-inset-left, 0px) + ${PAD}px)`
            : PAD,
          gap: GAP, overflow:'hidden',
          alignItems: isLandscapeMode ? 'flex-start' : 'center',
          justifyContent: isLandscapeMode ? 'center' : 'flex-start' }}>

          {/* Canvas */}
          <div
            style={{
              width: cw, height: ch, flexShrink: 0, position:'relative',
              background: '#fff',
              border: `1.5px solid #ECE4D3`,
              borderRadius: 22,
              boxShadow: `${M.shadowIn}, 0 2px 0 rgba(45,80,53,.04)`,
              backgroundImage: 'radial-gradient(circle at 1px 1px, rgba(45,80,53,0.08) 1px, transparent 0)',
              backgroundSize: '18px 18px',
              overflow: 'hidden',
              cursor: moveMode ? 'grab' : 'crosshair',
              touchAction: moveMode ? 'none' : 'manipulation',
            }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPointerCancel={onPointerUp}
          >
            <style>{`.milo-svg-container svg { width: 100% !important; height: 100% !important; display: block !important; }`}</style>
            <div
              className="milo-svg-container"
              ref={svgContainerRef}
              style={{
                width:'100%', height:'100%',
                transform: `scale(${zoom}) translate(${pan.x/zoom}px,${pan.y/zoom}px)`,
                transformOrigin:'center center',
                transition: isPanning.current ? 'none' : 'transform 0.15s ease',
                display:'flex', alignItems:'center', justifyContent:'center',
              }}
            />
            <StoryModal/>
          </div>


          {/* Sidebar */}
          <Sidebar/>
        </div>
      )}

      {/* Tutorial overlay (first-run + on-demand) */}
      {showTutorial && screen === 'coloring' && (() => {
        const totalSteps = t.tutorialSteps.length;
        const step = t.tutorialSteps[tutorialStep];
        const isLast = tutorialStep === totalSteps - 1;
        const next = () => isLast ? dismissTutorial() : setTutorialStep(s => s + 1);

        // Pill-styled icon matching the actual app buttons
        const IconPill = ({ children, active=false }) => (
          <div style={{
            width:54, height:54, borderRadius:16,
            background: active ? '#E6EFE0' : '#FDFBF5',
            border: `1px solid ${active ? M.greenDk : '#ECE4D3'}`,
            color: M.greenDk,
            display:'inline-flex', alignItems:'center', justifyContent:'center',
            boxShadow:'0 2px 0 rgba(45,80,53,.08)',
          }}>{children}</div>
        );

        // Icons matching the real buttons (1-to-1 SVG copies)
        const stepIcons = [
          // 1. Color palette — show 5 sample swatches
          <div style={{ display:'flex', gap:8, alignItems:'center' }}>
            {COLORS.slice(0, 6).map((c, i) => (
              <div key={i} style={{
                width:30, height:30, borderRadius:'50%', background:c,
                border: i === 0 ? `3px solid ${M.greenDk}` : '2px solid rgba(0,0,0,.08)',
                boxShadow:'0 2px 4px rgba(0,0,0,.08)',
              }}/>
            ))}
          </div>,
          // 2. Pencil + Hand
          <div style={{ display:'flex', gap:10 }}>
            <IconPill active>
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z"/></svg>
            </IconPill>
            <IconPill>
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12V7a2 2 0 0 1 4 0v4"/><path d="M9 11V5a2 2 0 0 1 4 0v6"/><path d="M13 11V6a2 2 0 0 1 4 0v7"/><path d="M17 13v-2a2 2 0 0 1 4 0v5a6 6 0 0 1-6 6H11a6 6 0 0 1-6-6v-2"/></svg>
            </IconPill>
          </div>,
          // 3. Story (hamburger) — same icon as in header
          <IconPill>
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M4 7h16M4 12h16M4 17h16"/></svg>
          </IconPill>,
          // 4. Save (download arrow)
          <IconPill>
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
          </IconPill>,
          // 5. Next button — actual pill style
          <div style={{
            display:'inline-flex', alignItems:'center', gap:8,
            padding:'10px 18px', borderRadius:9999,
            background:M.greenDk, color:'#fff',
            fontFamily:"'Baloo 2',cursive", fontWeight:700, fontSize:'0.95rem',
          }}>
            {t.nextBtn}
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
          </div>,
        ];

        return (
          <div
            onClick={dismissTutorial}
            style={{
              position:'fixed', inset:0, zIndex:9998,
              background:'rgba(20,25,21,0.78)',
              backdropFilter:'blur(4px)', WebkitBackdropFilter:'blur(4px)',
              display:'flex', alignItems:'center', justifyContent:'center',
              padding:20,
              animation:'mFadeIn 0.25s ease-out',
            }}
          >
            <div
              onClick={(e) => e.stopPropagation()}
              style={{
                background:'#FFF8E7',
                borderRadius:24,
                padding:'28px 26px 22px',
                maxWidth:380, width:'100%',
                boxShadow:'0 24px 60px -10px rgba(0,0,0,0.4)',
                fontFamily:"'Quicksand','Baloo 2',sans-serif",
                textAlign:'center',
                position:'relative',
              }}
            >
              {/* Header */}
              <div style={{ fontSize:'0.78rem', fontWeight:700, color:M.brown, letterSpacing:'.08em',
                textTransform:'uppercase', marginBottom:14, opacity:.6 }}>
                {t.tutorialTitle} · {tutorialStep + 1}/{totalSteps}
              </div>

              {/* Icon — matches real app buttons */}
              <div style={{ display:'flex', justifyContent:'center', marginBottom:16, minHeight:54 }}>
                {stepIcons[tutorialStep]}
              </div>

              {/* Title */}
              <div style={{ fontFamily:"'Baloo 2',cursive", fontWeight:800, fontSize:'1.5rem',
                color:M.greenDk, marginBottom:10, lineHeight:1.2 }}>
                {step.title}
              </div>

              {/* Body */}
              <div style={{ color:M.brown, fontSize:'1rem', lineHeight:1.5, marginBottom:22 }}>
                {step.text}
              </div>

              {/* Progress dots */}
              <div style={{ display:'flex', gap:6, justifyContent:'center', marginBottom:22 }}>
                {t.tutorialSteps.map((_, i) => (
                  <div key={i} style={{
                    width: i === tutorialStep ? 22 : 8, height:8, borderRadius:9999,
                    background: i === tutorialStep ? M.greenDk : 'rgba(45,80,53,.22)',
                    transition:'all 0.25s',
                  }}/>
                ))}
              </div>

              {/* Buttons */}
              <div style={{ display:'flex', gap:10, justifyContent:'center' }}>
                {!isLast && (
                  <button
                    onClick={dismissTutorial}
                    style={{
                      padding:'12px 22px', borderRadius:9999, border:'2px solid rgba(45,80,53,.2)',
                      background:'transparent', color:M.greenDk, fontFamily:"'Quicksand',sans-serif",
                      fontWeight:700, fontSize:'0.95rem', cursor:'pointer',
                    }}
                  >
                    {t.tutorialSkip}
                  </button>
                )}
                <button
                  onClick={next}
                  style={{
                    padding:'12px 28px', borderRadius:9999, border:0,
                    background:M.greenDk, color:'#fff',
                    fontFamily:"'Baloo 2',cursive", fontWeight:700, fontSize:'1rem',
                    cursor:'pointer', boxShadow:'0 4px 0 rgba(31,42,36,.3)',
                    display:'inline-flex', alignItems:'center', gap:8,
                  }}
                >
                  {isLast ? t.tutorialDone : t.tutorialNext}
                  {!isLast && <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>}
                </button>
              </div>
            </div>
          </div>
        );
      })()}

      {/* Export modal */}
      {exportImg && (
        <div
          onClick={() => setExportImg(null)}
          style={{
            position: 'fixed', inset: 0, zIndex: 9999,
            background: 'rgba(0,0,0,0.82)',
            backdropFilter: 'blur(22px)',
            WebkitBackdropFilter: 'blur(22px)',
            display: 'flex', flexDirection: 'column',
            alignItems: 'center', justifyContent: 'center',
            gap: 16, padding: 20,
          }}
        >
          {/* Instruction card */}
          <div
            onClick={e => e.stopPropagation()}
            style={{
              background: 'rgba(255,255,255,0.1)',
              border: '1px solid rgba(255,255,255,0.18)',
              borderRadius: 14, padding: '12px 22px',
              textAlign: 'center', maxWidth: 320,
            }}
          >
            {isIOS ? (
              <>
                <p style={{ fontFamily:"'Nunito',sans-serif", color: 'rgba(255,255,255,0.92)', fontSize: '0.88rem', lineHeight: 1.8, margin: 0 }}>
                  {t.iosSaveHint}
                </p>
                <p style={{ fontFamily:"'Nunito',sans-serif", color: 'rgba(255,255,255,0.45)', fontSize: '0.75rem', margin: '6px 0 0' }}>
                  {t.tapToClose}
                </p>
              </>
            ) : (
              <>
                <p style={{ fontFamily:"'Nunito',sans-serif", color: 'rgba(255,255,255,0.92)', fontSize: '0.88rem', lineHeight: 1.8, margin: '0 0 10px' }}>
                  {t.imageReady}
                </p>
                <button
                  onClick={() => {
                    const a = document.createElement('a');
                    a.href = exportImg;
                    a.download = `milo-pagina-${currentPage + 1}.png`;
                    a.click();
                  }}
                  style={{
                    fontFamily:"'Nunito',sans-serif", fontWeight: 800, fontSize: '0.9rem',
                    padding: '10px 28px', borderRadius: 40,
                    background: M.green, color: '#fff', border: 'none',
                    cursor: 'pointer', boxShadow: '0 4px 16px rgba(74,124,89,0.4)',
                  }}
                >
                  {t.downloadBtn}
                </button>
                <p style={{ fontFamily:"'Nunito',sans-serif", color: 'rgba(255,255,255,0.45)', fontSize: '0.75rem', margin: '8px 0 0' }}>
                  {t.tapToClose}
                </p>
              </>
            )}
          </div>

          {/* Image (long-press on iOS → Adicionar à Fotos) */}
          <img
            src={exportImg}
            alt="Página colorida"
            onClick={e => e.stopPropagation()}
            style={{
              maxWidth: '100%', maxHeight: '68vh',
              borderRadius: 12,
              border: '1px solid rgba(255,255,255,0.15)',
              boxShadow: '0 0 60px rgba(0,0,0,0.6)',
            }}
          />
        </div>
      )}

      {/* Toast */}
      <div style={{
        position:'fixed', bottom:20, left:'50%',
        transform: toastMsg ? 'translateX(-50%) translateY(0)' : 'translateX(-50%) translateY(80px)',
        background: M.greenDk, color:'#fff',
        padding:'9px 20px', borderRadius:100,
        fontFamily:"'Nunito'", fontSize:'0.8rem', fontWeight:800,
        boxShadow:'0 4px 20px rgba(45,80,53,0.35)',
        transition:'transform 0.3s cubic-bezier(0.34,1.56,0.64,1)',
        zIndex:200, whiteSpace:'nowrap', pointerEvents:'none',
      }}>{toastMsg}</div>
    </div>
  );
}

